package com.chubb.apac.claims.modulith.assessment.mapper;import com.chubb.apac.claims.modulith.assessment.dto.response.*;import com.chubb.apac.claims.modulith.assessment.model.*;import com.chubb.apac.claims.modulith.common.enums.ClaimStatus;import java.time.*;import org.springframework.stereotype.Component;
@Component public class AssessmentMapper{public AssessmentResponse toResponse(Assessment a){return new AssessmentResponse(a.getAssessmentId(),a.getClaimId(),a.getAssessorId(),null,a.getFindings(),a.getRecommendedDecision(),a.getRecommendationReason(),a.getEstimatedLiability(),java.util.List.copyOf(a.getRiskFactors()),a.getStatus(),a.getSubmittedAt(),a.getCreatedAt());}public PendingAssessmentResponse toPending(Assessment a){long days=a.getSubmittedAt()==null?0:Duration.between(a.getSubmittedAt(),Instant.now()).toDays();return new PendingAssessmentResponse(a.getAssessmentId(),a.getClaimId(),null,null,a.getRecommendedDecision(),a.getFindings(),a.getSubmittedAt(),days);}public DecisionResponse toResponse(DecisionRecord d,ClaimStatus status){return new DecisionResponse(d.getDecisionId(),d.getClaimId(),d.getDecision(),d.getReason(),d.getDeciderId(),null,d.getDecisionDate(),status);}}
